-- One self-contained record following DocumentIngestSchema.
CREATE TABLE IF NOT EXISTS legal_documents (
  id TEXT PRIMARY KEY,
  title TEXT NOT NULL,
  "originalTitle" TEXT,
  "documentType" TEXT NOT NULL CHECK ("documentType" IN ('constitution','act','regulation','schedule_only')),
  "yearBs" NUMERIC NOT NULL,
  "yearAd" NUMERIC NOT NULL,
  "totalPages" INTEGER NOT NULL CHECK ("totalPages" >= 0),
  nodes JSONB NOT NULL
);

INSERT INTO legal_documents (id,title,"originalTitle","documentType","yearBs","yearAd","totalPages",nodes) VALUES ($CODEx16b0e494522c$doc_the_environment_protection_act_2019_2076__2019_the-environment-protection-act-2019-2076_2021-12-03_06-38-31_pd$CODEx16b0e494522c$,$CODEx4c7384c633c9$The Environment Protection Act, 2019 (2076)$CODEx4c7384c633c9$,NULL,$CODEx76f3b5a7170a$act$CODEx76f3b5a7170a$,2076,2019,24,$CODExa79a5959984a$[{"tier": 1, "nodeType": "preamble", "identifier": "Preamble", "title": "Introductory matter", "content": "www.lawcommission.gov.np \n1 \n \nThe Environment Protection Act, 2019 (2076)  \nDate of Authentication  \n2076.06.24 ( 11th October , 2019 ) \nAct No. 9 of the year 2019 (2076)  \nAn Act Made to Amend and Consolidate Law Relating to  Environment  \nPreamble:  \nWhereas, it is expedient to amend and consolidate the prevailing law on \nenvironmental protection in order to protect the fundamental right of each citizen to  live \nin a clean and healthy environment , provide the victim with compensat ion by the polluter \nfor any damage resulting from environmental pollution or degradation, maintain a proper \nbalance between environment and development, mitigate adverse environmental impacts \non environment and biodiversity and face the challenges posed by  climate change;  \nNow, therefore, the Federal Parliament has made this Act .", "children": []}, {"tier": 1, "nodeType": "chapter", "identifier": "Chapter -1", "title": "Chapter -1", "content": null, "children": [{"tier": 2, "nodeType": "section", "identifier": "1", "title": "Short title and commencement: (1) This Act  may be cited as the  \"Environment", "content": "Protection Act,  2019 (2076).  \n(2) This Act shall commence on the eighth day of the date on which it \nis authenticated.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "2", "title": "Definitions:  Unless the subject or the context otherwise requires, in this Act:", "content": "(a) “Adaptation” means the prevention or mitigation of further loss and \ndamage upon projecting potential impacts and risks of climat e \nchange.  \n(b) “Emission” means emission of greenhouse gas or any other gas, \nsmoke or dust on the environment from any certain area in a certain \nperiod.  \n(c) “Fund” means the environment protection fund referred to in \nSection 31.  \n(d) “Climate change”  means a gradual change of climate of the earth \nwhich is attributed directly or indirectly to human activity that alters \nthe composition of the global atmosphere and which is in addition \nwww.lawcommission.gov.np \n2 \n \nto natural climate variability observed over comparable time \nperiods.  \n(e) “Climate change management” means the mitigation or adaptation \nof problems arising as a result of climate change, and this term also \nincludes a totality of acts including policies, strategies, making \ninstitutional mechanisms, provision of finance, cap acity building.  \n(f) “Hazardous substance” means any substance enlisted in the Basel \nConvention on the Control of Transboundary Movement  of \nHazardous Wastes and  Their Disposal, and  explosives, \ninflammable, perpetual and substances with corrosive \nproperties and substances that are intended to be in use for the \nfirst time upon be processed from raw materials not re -used \nwhich cause adverse impact on the environment.  \n(g) \"Biological diversity\" means eco -system diversity, species diversity \nand genetic diversity.  \n(h) “Prescribed” or “as prescribed” means prescribed or as prescribed \nin the rules framed under this Act.  \n(i) “Mitigation” means reduction or prevention of emission of \ngreenhouse gas as a result of human activity.  \n(J) \"Pollution\" means the activities that  significantly degrade, damage \nthe environment or harm the beneficial or useful purpose of the \nenvironment, by changing the environment directly or indirectly as \na result of wastes, chemical, heat, noise, electrical, electro -magnetic \nwave or radioactive ra y. \n(k) \"Proposal\" means a proposal prepared in regard to the carrying out \nof such development work, physical activity that may bring about \nchange in the existing environmental conditions or any plan, project \nor programme which changes the land use.  \n(l) \"Proponent\" means a person or governmental, semi -governmental \nor non -governmental agency or institution that makes application \nfor the approval of a proposal or that has go t approval for the \nimplementation of the proposal.   \n(m) \"Initial environmental examination\" means an analytical study or \nevaluation to be conducted to ascertain as to whether, in \nwww.lawcommission.gov.np \n3 \n \nimplementing a proposal, the proposal does have significant adverse \nimpacts on the environment or not, and with respect to the measur es \nto be adopted for avoiding or mitigating such impacts by any means.  \n(n) “Supplementary environmental impact assessment” means an \nenvironmental impact assessment to be made again vis -à-vis a \nproposal submitted in order to make revision partly in physica l \ninfrastructure, design or form, transfer or alter a structure, add a \nforest area or increase the project capacity on the environmental \nimpact assessment proposal which has been already accepted.  \n(o) “Council” means the national council on environment pro tection \nand climate change management referred to in Section 32.  \n(p) “Provincial Ministry” means the Ministry of a Provincial \nGovernment responsible for environment related matter.  \n(q) \"Wastes\" means the liquid, solid, gas, slurry, smoke, dust, radiated \nelement or substance or similar other materials disposed in a manner \nto degrade the environment.  \n(r) \"Ministry\" means the Ministry of Forest and Environment of the \nGovernment of Nepal.  \n(s) \"National heritage\" means any such object, physical structure, site, \nplant or animal related with the environment available within Nepal \nas is likely to be important to the human being from natural, cultural, \nhistorical, archaeological, scientific, spiritu al, aesthetic or social \npoint of view.  \n(t) \"Environment\"  means the interaction and inter -relationship among \nthe components of natural, cultural and social systems, economic \nand human activities and their components . \n(u) “Environmental study report” means a report prepared with respect \nto the brief environmental study, initial environmental examination \nor environmental impact assessment.  \n(v) \"Environmental impact assessment\" means detailed study and \nevaluation to be made to ascertain as to whether, in imple menting a \nproposal, the proposal does have significant adverse impacts on the \nenvironment or not, and as to the measures to be adopted for \navoiding or mitigating such impacts.  \nwww.lawcommission.gov.np \n4 \n \n(w) “Department” means the Department of Environment under the \nMinistry.  \n(x) “Concerned body” means the body referred to in sub -section (2) of \nSection 3  which is responsible for taking action and decision on the \nenvironmental study report.  \n(y) “Brief environmental study” means a study to be made briefly as to \nthe measures to be adopte d for avoiding or mitigating the adverse \neffects on the environment as a result of implementation of any \nproposal.  \n(z) “Local Level” means a Rural Municipality or Municipality.", "children": []}]}, {"tier": 1, "nodeType": "chapter", "identifier": "Chapter -2", "title": "Chapter -2", "content": null, "children": [{"tier": 2, "nodeType": "section", "identifier": "3", "title": "Environmental study report to be prepared: (1) A proponent shall prepare such", "content": "an environmental study report of such a proposal as may be prescribed.  \n  (2) The environmental study report prepared pursuant to sub -section \n(1) shall, in fulfillment of the process as prescribed, be submitted to the \nfollow ing body for approval:  \n(a) To the prescribed body , in the case of a brief environmental study \nreport or initial environmental examination of a development \nproject with national priority, a project to be implemented upon its \ninvestment being approved by the  Investment Board, a project of \nnational pride, a development or construction work or project falling \nunder the jurisdiction of the Federation in accordance with the \nprevailing, a project requiring construction work to be done in more \nthan one Provinces or  a project specified by the Government of \nNepal , and to the Ministry in the case of the environmental impact \nassessment,  \n(b) To the body prescribed by the concerned Provincial law in the case \nof a proposal relating to development, construction work or proj ect \npertaining to a matter f alling under the jurisdiction of the Provincial \nGovernment,  \n(c) To the body designated by the concerned local law in the case of a \nbrief environmental study report or initial environmental \nwww.lawcommission.gov.np \n5 \n \nexamination report on a proposal relati ng to development, \nconstruction work or project pertaining to a matter falling under the \njurisdiction of the Local Level, and  to such body of the Provincial \nGovernment as prescribed by the Provincial Government in the case \nof an environmental impact assessment report.  \n(3) Notwithstanding anything contained in sub -section (1) or (2), \nnothing shall bar the approving of environmental study reports submitted for \napproval at the time of commencement of this Act in accordance with t he legal \nprovisions in force at the time of submission of such reports.  \n(4) Notwithstanding anything contained elsewhere in this Section, there \nshall not be required an environmental study report for reconstructing as such a \nheritage considered an ancient  monument , in accordance with the law relating to \nancient monuments.  \n(5) In preparing an environmental study report, the proponent shall \nhold, as prescribed, a public hearing as to the proposal.  \n(6) Other provisions relating to the submission of an environ mental \nstudy report shall be as prescribed.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "4", "title": "Detailed analysis of alternative to be made: (1) The proponent shall make", "content": "detailed analysis  of possible adverse effects on the environment from the \nimplementation of such a proposal and various alternatives th at can be adopted for \nmitigation such effects, and recommend the alternative that is appropriate for the \nimplementation of the proposal and the grounds and reasons why that alternative \nis implementable.  \n  (2) In preparing the environmental study report pur suant to sub -section \n(1), the proponent shall set out, inter alia, the possible short -term, mid -term and \nlong-term adverse effects on the environment from the implementation of the \nproject and the method and process to be adopted for mitigation thereof.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "5", "title": "Scoping and work schedule : (1) Prior to preparing the environmental study report", "content": "of any proposal pursuant to this Act, the scope  of such a proposal,  in the case of a \nbrief environmental study and initial environmental examination, and scope and \nwork schedule, in the case of an environmental impact assessment shall be \napproved by the concerned body.  \n  (2) Other provisions on the scoping and preparation of the work \nschedule referred to sub -section (1) and approval thereof shall be as prescribed.  \nwww.lawcommission.gov.np \n6", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "6", "title": "Standards and quality to be maintained: (1) In preparing an environmental", "content": "study report pursuant to this Act, the proponent shall so prepare it in the form as \nprescribed that the standards and quality determined by the Government of Nepal \nare maintained.  \n  (2) If the report is submitted contrary to the standards or qualify \nreferred to in sub -section (1) or without complying with such standards, the \nconsultant w ho has prepared such a report shall not be allowed to prepare an \nenvironmental study report for a perio d not exceeding five years.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "7", "title": "Environmental study report to be approved:  (1) If an environmental study", "content": "report prepared in the context of the implementation of any proposal pursuant to \nSection 3 is received, the concerned body shall make necessary inquiry into the \nreport.  \n  (2) The concerned body may form a committee comprising a \nrepresentative of that body, representatives of the relevant bodies concerned with \nthe proposal and subject expert as required, to inquire into the environmental study \nreport recei ved pursuant to sub -section (1) and furnish advice and suggestions.  \n  (3) If, in inquiring into the environmental study report received \npursuant to sub -section (1), it appears that further environmental study has to be \nmade in relation to such a proposal, the concerned body shall give order to the \nproponent to make, or cause to be made, the initial environmental examination in \nthe case of the brief environmental study or the environmental impact assessment \nin the case of the brief environmental study.  \n  (4) The proponent shall make further study in pursuance of the order \ngiven pursuant to sub -section (3) and submit a report thereof to the concerned \nbody.  \n  (5) If, in making inquiry pursuant to this Section, it does not appear that \nthe implementation of such a proposal causes significant adverse impacts on the \nenvironment, the concerned body shall approve such environmental study report, \nupon specifying the terms and conditions to be observed by the proponent, as \nrequired.  \n  (6) Other provisions relating to th e approval of the environmental study \nreport shall be as prescribed.  \nwww.lawcommission.gov.np \n7", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "8", "title": "Proposal not to be implemented: No person shall implement, or cause to be", "content": "implemented, any proposal without having the environmental study report \napproved pursuant to this Act.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "9", "title": "Strategic environmental analysis:  (1) Prior to the implementation of such policy,", "content": "program or project as may be specified by the Government of Nepal by a \nnotification in the Nepal Gazette, the strategic environmental analysis shall be \ncarried out in relation to  such a policy, program or project.  \n  (2) Other provisions relating to the strategic environmental analysis \nshall be as prescribed.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "10", "title": "Environmental management plan:  (1) Prior to the implementation of a proposal,", "content": "the proponent shall prepare an environment al management plan as prescribed.  \n  (2) In preparing the environmental management plan pursuant to sub -\nsection (1),  the proponent shall set out, inter alia, which of the measures to mitigate \nenvironmental adverse impacts will be adopted in the course of bu ilding the \nproject and which of such measures will be adopted after the completion, or in the \ncourse of implementation, of the project.  \n  (3) If it does not appear that the measures to mitigate environmental \nadverse impacts set out by the proponent in the environmental management plan  \npursuant to sub -section ( 2) are effective, the concerned body may give necessary \ndirection to adopt other effective measures, and the concerned proponent shall bear \nthe expenses incurred in the implementation of the direction so given by the \nconcerned body.  \n  (4) The proponent shall  make a clear action plan for the implementation \nof e nvironmental management plan prepared pursuant to sub -section (1)  and \nimplement it accordingly, and submit its progress report to the concerned body in \nevery six months after the commencement of the proj ect implementation.  \n  (5) In adopting the measures to mitigate environmental adverse impacts \nin the course of implementation of the e nvironmental management plan referred \nto in sub-section (1) , priority shall be given to the operation of the program throug h \nthe local community which affected from the implementation of the proposal.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "11", "title": "Supplementary environmental impact assessment to be made:  (1) If it is", "content": "required to make some revision in the physical infrastructure, design or form, \ntransfer or alter the structure  of any project of which the environmental impact \nassessment report has been approved pursuant to Section 7 , add the forest area or \nwww.lawcommission.gov.np \n8 \n \nincrease the capacity  of the project, the proponent shall make a supplementary \nenvironmental impact assessment in ord er to ascertain whether the operation of \nsuch work causes adverse impacts on the environment or not, and whether such \nimpacts can be done away with or mitigated by any means or not.  \n  (2) The proponent shall, i n order to make the supplementary \nenvironmental impact assessment pursuant to sub -section (1),  make an application \nto the concerned body, along with an analysis of the reasons for making changes \nin various components of the project and possible adverse impacts on the \nenvironment from such changes, a comparative table according to environmental \nindicators and other necessary justifications.  \n  Provided that where the concerned body has given order to the proponent \nto submit a supplementary environmental impact assessment  report, the proponent \nneed not make an application.  \n  (3) If the content is found reasonable upon inquiring into the application \nreceived pursuant to sub -section (2), the concerned body may give permission for \na supplementary environmental impact assessme nt study as prescribed.  \n  (4) Other provisions relating to the supplementary environmental \nimpact assessment  shall be as prescribed.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "12", "title": "To make environmental examination after commencement of service: (1) The", "content": "Ministry or prescribed body shall, not later t han six months of the date of \ncompletion of two years of the commencement of production or distribution of the \nservice or goods  or of the  implementation of a proposal requiring the \nenvironmental impact assessment pursuant to this Act , make analysis of the \nadverse impacts  on the environment as a result of the implementation of such a \nproposal, measures adopted to mitigate such impacts, effectiveness of such \nmeasures, adverse impacts that could not be mitigated or occurrence of any \nunprojected /unforeseen  adverse impacts and maintain  undated records of  the \nenvironmental examination report.  \n  (2) If the Ministry or prescribed body does not see , upon making \nnecessary study, in coordination with the concerned body with respect to the \nenvironmental examination repo rt referred to in sub -section (1), that the measures  \nadopted to mitigate the adverse impacts on the environment are not adequate, it \nmay give appropriate order to the proponent to do away with or mitigate such \nadverse impacts.  \nwww.lawcommission.gov.np \n9 \n \n  (3) It shall be the duty of  the proponent to implement the order given \nby the Ministry or prescribed body pursuant to sub -section (2).", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "13", "title": "Power to prevent : (1) If any person executes a project without having the", "content": "environmental study report approved pursuant to this Act or contrary to the \napproved environmental study report, the concerned body may immediately \nprevent the project from being executed.  \n  (2) Where a project is prevented from being executed pursuant to sub -\nsection (1) and such prevention results in any harm to the propon ent, the proponent \nshall not be allowed to make a claim of compensation for such harm.  \n  (3) Notwithstanding anything contained in sub -section (1), if the \nproponent of the project prevented from being executed gets the environmental \nstudy report to be app roved pursuant to this Act or makes improvement in the \nproject execution in accordance with the approved environmental study report, the \nconcerned body may release the prevention made pursuant to sub -section (1).", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "14", "title": "Power of the Government of Nepal or Pro vincial Government to make", "content": "environmental study:  (1) The Government of Nepal or Provincial Government \nmay, on its own, map out  any area or place and make the environmental study of \nthat area.  \n  (2) The concerned body shall, on the basis of the descriptions  obtained \nfrom the study referred to in sub -section (1)  shall prepare descriptions as to such \ndevelopment, construction works or projects that can be executed in such area in \nthe future and work that is not appropriate for execution in such area.  \n  (3) The concerned body shall maintain records of the descriptions \nobtained from the study referred to in sub -section (1)  and the descriptions referred \nto in sub -section ( 2). \n  (4) The concerned body shall make public the descriptions referred to \nin this Section, a nd the concerned proponent, body and party concerned shall act \nin consistent therewith.", "children": []}]}, {"tier": 1, "nodeType": "chapter", "identifier": "Chapter -3", "title": "Chapter -3", "content": null, "children": [{"tier": 2, "nodeType": "section", "identifier": "15", "title": "Control of pollution:  (1) The Government of Nepal may, by a notification in the", "content": "Nepal Gazette, determine necessary standards for the mitigation or doing away \nwith the impacts  of pollution from any motor vehicle, device, equipment, \nwww.lawcommission.gov.np \n10 \n \nindustrial enterprise , hotel, restaurant or ot her place or goods or activity or effects \nfrom the disposal or emission of any hazardous substance.  \n  (2) No person shall create pollution in such a manner as to cause \nsignificant adverse impacts on the public life, public health and environment or \ndo, or cause to be done, any act contrary to the standards determined by the \nGovernment of Nepal pursuant to sub -section (1).  \n(3) No person or group that visits a mountain or high hill area  for \nexpedition, trekking, sightseeing or any other purpose shall do, or c ause to be \ndone, any such act that may cause adverse impacts on the environment by making \npollution contrary to the standards determined by the Government of Nepal.  \n(4) If it appears that any one has caused adverse impacts on the \nenvironment by doing  any a ct contrary to sub -section (1) or (2), the Department \nmay give direction to the relevant person, group or institution to take measures for \nmitigation of or doing away with  pollution, prescribe necessary terms or prohibit \nthe carrying out of any act in a ma nner to cause adverse impacts on the \nenvironment .   \n  (5) If it appears that the use of any substance, fuel, tool, machine or \nequipment has caused or is likely to cause significant adverse impacts on the \nenvironment, the Department may request the Ministry  for necessary action.  \n  (6) If a request is received from the Department pursuant to sub -section \n(5), the Ministry may, in necessary consultation with the concerned body or other \nstakeholders, prevent  the use of such substance, fuel, tool , device  or equip ment or \nthe production, import, sale, distribution or storage of such materials, and a notice \non such prevention shall be published in the Nepal Gazette.  \n  (7) The Department shall, from time to time, carry out monitoring and \nevaluation as to compliance with the standards determined pursuant to sub -section \n(1). \n  (8) Other provisions relating to the control of pollution shall be as \nprescribed.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "16", "title": "Export and import of hazardous substance : (1) No hazardous substance of any", "content": "kind shall be imported into Nepal.  \n  (2) Notwithstanding anything contained in sub-section (1) , any such \nspecific kind of hazardous substance that does not cause significant adverse \nwww.lawcommission.gov.np \n11 \n \nimpacts on the human health and environment as specified by the Government of \nNepal by a notification in the Nepal Gazette may be impor ted. \n  (3) A producer of a hazardous substance or person or body established \nunder prevailing law may export hazardous substance by obtaining permission \nfrom the Ministry.  \n  (4) Grounds, criteria for issuance of, and other provisions relating to, \npermission to export a hazardous substance pursuant to sub -section (3) shall be as \nprescribed.  \n  (5) A hazardous substance imported contrary to this Act shall be sent to \nthe same country from which it has been imported.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "17", "title": "Manageme nt of a hazardous substance: (1) The person or body that produces a", "content": "hazardous substance shall be responsible for managing such a hazardous \nsubstance.  \n  (2) In collecting, storing, processing, selling, distributing, disposing or \ntransporting a hazardous sub stance, the concerned person or body shall make its \nproper management in a manner not to cause adverse impacts on the environment.  \n  (3) The concerned person or body shall manage the hazardous substance \npursuant to sub -section (1) at his or her own cost.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "18", "title": "Power to establish laborator ies: (1) The Government of Nepal or Provincial", "content": "Government may establish laboratories , as required , to carry out test or \nexamination relative to environment protection and pollution control or prescribe \nany laboratory  recogniz ed by the Government of Nepal  to carry out test or \nexamination  relative to environment protection and pollution control.   \n(2) Provisions relating to  the operation and management of the \nlaboratory established pursuant to sub -section (1) shall be as prescri bed.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "19", "title": "To allow collection of samples: (1) If the concerned body intends to study, test,", "content": "examine or analyze the pollution or wastes to be or likely to be generated from \nany industry, factory, mechanical equipment like a machine and motor vehicle, the \nconcerned owner or relevant person shall allow to collect samples of the pollution \nor wastes generated from  such industry, factory, mechanical equipment like a \nmachine and motor vehicle.  \n  (2) Other provisions relating to the collection, study, examination , test \nor analysis of samples pursuant to sub -section (1) shall be as prescribed.  \nwww.lawcommission.gov.np \n12", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "20", "title": "Power to issue pollution control certificate:  (1) The Ministry or Provincial", "content": "Ministry may  provide  a pollution control certificate, as prescribed, to any industry \nthat mak es a significant contribution to the control of pollution.  \n  (2) Other provisions relating to the pollution control certificate shall be \nas prescribed.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "21", "title": "Environmental inspector:  (1) The environmental inspector shall  carry out", "content": "monitoring and inspection a s to whe ther or not  acts to be  performed  in accordance \nwith the environmental study report  approved pursuant to Section 7 have been \nperformed effectively  and standards relating to pollution control and \nenvironmental protection have been complied with.  \n  (2) Notwithstanding anything contained in sub -section (1), in cases \nwhere the environmental inspector is not available, the following body may \ndesignate the following officer or employee as the environmental inspector and \ndepute such officer or employee fo r monitoring and inspection:  \n(a) The Ministry may designate any officer employee of the \nGovernment of Nepal or Provincial Government, as to whether or \nnot acts to be performed in accordance with the environmental study \nreport referred to in clause (a) of s ub-section (2) of Section 7 have \nbeen performed effectively and standards relating to pollution \ncontrol and environmental protection have been complied with , \n(b) The Provincial Ministry may designate any officer employee of the \nProvincial Government, as to  whether or not acts to be performed in \naccordance with the environmental study report referred to in clause \n(b) of sub -section (2) of Section 3 approved pursuant to Section 7 \nor the environmental impact assessment report referred to in clause \n(c) of sub -section (2) of Section 3 have been performed effectively \nand standards relating to pollution control and environmental \nprotection have been complied with within its Province,  \n(c) The Local Level may designate any employee of the Local Level, as \nto whether o r not acts to be performed in accordance with the \nenvironmental study report referred to in clause (c) of sub -section \n(2) of Section 3 approved pursuant to Section 7 have been performed \neffectively and standards relating to pollution control and \nwww.lawcommission.gov.np \n13 \n \nenvironmen tal protection have been complied with within its Local \nLevel.  \n(3) Other provisions relating to the environmental inspector shall be as \nprescribed.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "22", "title": "Functions, duties and powers of the environmental inspector:  (1) The", "content": "functions, duties and powers of the  environmental inspector shall be as follows:  \n(a) To inspect as to whether or not disposal of hazardous \nsubstances  has been made  or pollution has been caused \ncontrary to this Act or the rules framed under this Act,  \n(b) To inspect as to whether or not the acts of mitigation, \navoidance or control of pollution have been carried out in \naccordance with this Act or the rules framed under this Act,  \n  (c) To inspect on site as to whether or not work has been \nperformed consistent  with the terms prescribed in the \napproved environmental study report while executing the \nproposal,  \n(d) To inspect as to where the matters prevented pursuant to \nSection 13 or 15 have been complied with.  \n(2) In the course of making inspection pursuant to su b-section ( 1), the \nenvironmental inspector may, by giving a prior notice to the concerned person, \nbody or proponent, inspect, examine or investigate any house, land, building, \nfactory, industry, motor vehicle, industrial device, tools, machinery, animal, \nobject, records, document or other goods  or object .   \n(3) It shall be the duty of the  concerned person, body or proponent to \nrender assistance to the environmental inspector in the course of inspection \npursuant to this Section, by providing such descriptions or information as \ndemanded by him or her.  \n (4) If the concerned person or body does not allow  the environmental \ninspector to  make inspect ion, while moving on to make inspectio n pursuant to this \nSection , does not provide such descriptions or information as demanded by him or \nher, gives false descriptions, creates let and hinderance or does not assist in the \ncourse of inspection, the environmental inspector may immediately impose the \nfine as follows on such a person or body:  \nwww.lawcommission.gov.np \n14 \n \n(a) A fine of up to twenty thousand rupees  in case of disallowing him \nor her to make inspection or creation of let and hindrance in \ninspection,  \n(b) A fine of up to fifteen thousand rupees in case of failure to provide \nsuch descriptions or information as demanded or of giving f alse \ndescription in the course of inspection or failure to assist in \ninspection.  \n(5) A party  who is not satisfied with a punishment imposed  by the \nenvironmental inspector pursuant to sub -section ( 4) may make a complaint to the Director \nGeneral not later th an fifteen days of the date of receipt of information of that punishment.  \n(6) The environmental inspector shall submit a report of inquiry and inspection \ncarried out pursuant to this Section to the concerned body and the Department.  \n(7) Other functions, du ties and powers of the environmental inspector shall be \nas prescribed.", "children": []}]}, {"tier": 1, "nodeType": "chapter", "identifier": "Chapter -4", "title": "Chapter -4", "content": null, "children": [{"tier": 2, "nodeType": "section", "identifier": "23", "title": "To provide information: (1) The Ministry shall carry out study as prescribed, on", "content": "a periodic basis, as to the adverse impacts caused by climate change on the local \ncommunities, eco -system and bio -diversity and make public descriptions thereof.  \n  (2) The Ministry shall,  on the basis o f the study carried out pursuant to \nsub-section (1), and  from time to time, make public necessary information on such \nmeasures as to be adopted for the mitigation of adverse impacts or risks  from \nclimate change while formulating development projects to be executed by the \nGovernment of Nepal, Provincial Government and Local Level.  \n  (3) The Government of Nepal, Provincial Government and Local Level \nmay, on the basis of the information made public pursuant to sub -section (2), set \nthe priorities of formulation  of development projects.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "24", "title": "Adaptation plan may be made:  (1) In order to avoid adverse impacts and risks", "content": "of climate change, the Ministry, Provincial Ministry and Local Level may make \nand implement an adaptation plan at the national, Provincial and Local levels, \nrespectively.  \n  (2) In making the adaptation plac e referred to in sub -section (1), special \npriority shall be accorded to the women, persons with disabilities, children, senior \nwww.lawcommission.gov.np \n15 \n \ncitizens and economically indigent communities who are more vulnerable to \neffects of climate change and the inhabitants of those geographical areas that have \nbecome more vulnerable to climate change.  \n  (3) Local communities may make and implement an adaptation plan at \nthe local level, and the concerned body shall make necessary assistance and \nfacilitation in the implementation of su ch a plan.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "25", "title": "Power to carry out acts of mitigation: (1) The Government of Nepal may  identify", "content": "areas emitting green -house gas and determine  their national reference level.  \n  (2)  The Ministry shall make periodic monitoring as to the national \nreference leve l determined pursuant to sub -section (1) and make public the \nupdated information.  \n  (3) The Ministry, Provincial Government and Local Level may launch \nnecessary programs.  \n  (4) The Ministry may make, or cause to be made, measurement of \ngreen -house gas emis sion.  \n  (5) Other provisions relating to mitigation shall be as prescribed.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "26", "title": "Impacts from climate change and risk management:  (1) The Government of", "content": "Nepal may, for the purpose of managing adverse impacts and risks of climate \nchange, issue necessary order s, by a notification in the Nepal Gazette, as to such \nmeasures as to be adopted for the mitigation of adverse impacts and risks of \nclimate change, in the sectoral policies, strategies and action plans  to be executed \nby the Government of Nepal, Provincial G overnment, Local Level  and other public \nbodies as well as the private sector.  \n  (2) The Government of Nepal may prescribe priority while issuing any \norder pursuant to sub -section (1).", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "27", "title": "Power to determine technical standards: (1) The Government of Nepal may", "content": "determine and enforce necessary standards for the setting of priority of matters to \nbe implemented in urban and rural areas as to the mitigation of adverse impacts \nand risks of climate change.  \n  (2) The Government of Nepal may determine necessary polic y and \ntechnical standards for the development of such technology as may be necessary \nin the prescribed subject areas for the mitigation of adverse impacts and risks of \nclimate change.  \nwww.lawcommission.gov.np \n16", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "28", "title": "Power to participate in carbon trade:  (1) The Government of Nepal ma y", "content": "participate in carbon trade with the mechanisms established by the international \ntreaty, any foreign government or organization, business entity or private sector \nfor the mitigation and conservation  of carbon emission.  \n  (2) Other provisions relating to participation in carbon trade pursuant \nto sub -section (1) and allocation of benefits resulted therefrom shall be as \nprescribed.", "children": []}]}, {"tier": 1, "nodeType": "chapter", "identifier": "Chapter -5", "title": "Chapter -5", "content": null, "children": [{"tier": 2, "nodeType": "section", "identifier": "29", "title": "Protection of national h eritages:  (1) It shall be the duty of all the concerned", "content": "agency to protect national heritages.  \n(2) For the purpose of the protection of national heritages, the \nconcerned body shall to prepare and maintain an inventory, and such an inventory \nshall also inclu de the objects or places within Nepal which are listed in the World \nHeritage List.  \n(3) The objects, places, plants, animals, environment etc., included in \nthe inventory referred to in sub -section (2) shall be protected as prescribed.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "30", "title": "Special provision relating to environment protection areas:  (1) The", "content": "Government of Nepal may, in consultation with the Provincial Government and \nconcerned Local Level and by a notification in the Nepal Gazette, maintain as an \nenvironment protection area any place c ontaining a natural heritage or aesthetic \nplace which is considered extremely  significant from the point of view of \nenvironmental protection or any place of historical  or cultural importance . \n  (2) In making any road, building, river management or other ph ysical \ninfrastructures, the Government of Nepal may, in coordination with the concerned \nbody and by a notification in the Nepal Gazette, specify any specific area as an \nopen or green area with a view to protecting the environment of such area.  \n  (3) Prohib ition may be imposed on any such act as prescribed within \nthe environment protection area maintained pursuant to sub -section (1) or open or \ngreen area specified pursuant to sub -section (2) . \n  (4) In cases where it appears that adverse impacts have been cau sed, are \nlikely to be caused, on public health or environment of any specific area or place \nwww.lawcommission.gov.np \n17 \n \nas a result of excessive environmental pollution, soil erosion, excessive \nexploitation of natural heritages or occurrence of a natural calamity in such area \nor plac e, the Government of Nepal may, in consultation with the concerned Local \nLevel, issue any appropriate order for the balance, management or restoration of \nthe environment, upon specifying such an area or place as a sensitive area from \nthe environmental view point.  \n  (5) The Government of Nepal may specify any place in which any \ninjurious or hazardous substance or wastes are stored or disposed or there is \nexcessive pollution for other reason as a  polluted area and prevent the movement \nof public there.  \n  (6) In cases where there is improvement from the environmental \nviewpoint in the place referred to in sub -section (4) or (5), such area may be \nremoved from the list of sensitive area or polluted area.  \n  (7) Participation of the local community maybe forged in t he \nmanagement of any area maintained or specified pursuant to this Section for the \nprotection of environment.  \n  Explanation: For the purposes of this Section and Section 36, “local \ncommunity” means the community residing within or in neighborhood of such a n \narea.   \n  (8)  There shall be participation of the local community as prescribed \nin the benefits resulted from the management of the area managed pursuant to sub -\nsection (7).", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "31", "title": "Establishment and operation of fund : (1) There shall be established a fund", "content": "entitled the environment protection fund, for the protection of environment, \nprevention and control of pollution, management of climate change and protection \nof the national heritages.  \n(2) The following amounts shall be credited to the fund referred to in \nsub-section (1):   \n(a) Amount received from the Government of Nepal, Provincial \nGovernment or Local Level,  \n(b)  Amount received from any native person or organization,  \n(c) Amount received from any foreign government or international \norganization.  \nwww.lawcommission.gov.np \n18 \n \n(3) Prior  to obtaining the amount referred to in clause (c) of sub -section \n(2), approval of the Government of Nepal, Ministry of Finance shall be obtained.  \n(4) The fund shall be audited by the Auditor General.  \n(5) The operation of the fund shall be as prescribed.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "32", "title": "Power to constitute council : (1) There shall be an environmental protection and", "content": "climate change management national council  chaired by the Prime Minister,  for \nthe carrying out of acts relating to environmental protection and climate change  at \nthe national level in an effective manner.  \n  (2) The council referred to in sub -section (1) shall consist of the \nfollowing chairperson and members:  \n  (a) Prime Minister      -Chairperson  \n (b) Minster for Forest and Environment,  \nGovernment of Nepal     -Member  \n(c) Three Minsters of the Government of Nepal  \ndesignated by the Prime Minister    -Member  \n(d) Chief Ministers of all Provinces    -Minister  \n(e) Member of the National Planning Commission  \nwho looks af ter the matter of environment   -Member  \n(f) Two pe rsons including one woman nominated by  \nthe Chairperson from  among the professors  \nin fore st and environmental science   -Member  \n(g) Three persons including two women nominated by the  \nChairperson from among the persons with expertise  \nin the fi eld of forest and environment   -Member  \n(h) Secretary, Ministry     -Member -Secretary  \n(3) The chairperson may designate one Minister out of the members as \nthe vice -chairperson.  \n(4) The tenure of the members nominated pursuant to clauses (f) and (g) \nshall be three years.  \n(5) Notwithstanding anything contained in sub -section (4), if a \nnominated member fails perform the duties of his or her office, the chairperson \nmay remove him or her from the office of member.  \nProvided that, prior to such removal, he or she sh all be provided with a \nreasonable opportunity to submit clarification.  \nwww.lawcommission.gov.np \n19", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "33", "title": "Meetings and of the Council:  (1) The Council shall meet  at least once a year  at", "content": "such date, time and place as prescribed by the chairperson.  \n  (2) The member -secretary of the Counci l shall, in consultation with the \nchairperson send a notice setting out the date, time and place of the meeting of the \nCouncil, along with the agenda to be deliberated thereat, so that all the members \ncan receive it in advance of at least forty -eight hours  of the time of the meeting.  \n  Provided that in the event of a need for calling a meeting of the Council \nimmediately, the chairperson of the Council may call the meeting in advance of \nseventy -two hours, if the meeting is so called, the member -secretary of the \nCouncil shall as soon as possible send the notice thereof so that all the members \ncan receive it.  \n  (3) The presence of a majority of the total number of members shall be \ndeemed to constitute a quorum for the meeting of the Council.  \n  (4) The chairperson of the Council  shall preside over the meeting of the  \nCouncil,  and in the absence of the chairperson, the vice-chairperson of the Council \nshall preside over the meeting.  \n(5) Any decision of the Council shall be taken by a majority, and in the \ncase of a tie , the chairperson shall exercise the casting vote.  \n(6)  Any office -bearer, representative of concerned body or \norganization or environmental expert may, as required, be invited to the meeting \nof the Council.  \n(7) The member -secretary of the Counc il shall authenticate the decision \nof the Council .  \n(8) Other procedures relating  to the meeting of the Council shall be as \ndetermined by the Council  itself.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "34", "title": "Functions, duties and powers of the Council: (1) The functions, duties and", "content": "powers of the Counc il shall be as follows:  \n(a) To give direction, as required, to the Ministry and other bodies to \nkeep on integrating the matters relating to the environment and \nclimate change into the long -term policies, plans and programs,  \n(b) To set policy for the develo pment of a national system for the \ncontrol of pollution, management of wastes and protection of \nnational heritages , \nwww.lawcommission.gov.np \n20 \n \n(c) To give necessary policy guidance to the Provincial and Local levels \nwith regard to environment al protection  and climate change,  \n(d) To manage economic resources for environmental protection and \nclimate change and facilitate for the same,  \n(e) To give guidance to the Ministry for utilization, management, \ndevelopment and protection of natural, cultural and physical \nresources and heritages,  \n(f) To make evaluation of acts pertaining to environmental protection \nand climate change.", "children": []}]}, {"tier": 1, "nodeType": "chapter", "identifier": "Chapter -6", "title": "Chapter -6", "content": null, "children": [{"tier": 2, "nodeType": "section", "identifier": "35", "title": "Fine:  (1) If any person does the following act, the concerned body may punish", "content": "that person as follows:  \n(a) A fine not exceeding five hundred thousand rupees if, in the case of \na proposal of which the brief environmental study report has to be \napproved,  the proposal is executed without having it approved or if \nany proposal is executed in a manner inconsistent with the approved \nrepor t, \n(b) A fine not exceeding one million rupees if any proposal is executed \nwithout having the initial environmental examination approved or \nin a manner inconsistent with the approved report,  \n(c) A fine not exceeding five million rupees if, in the case of a  proposal \nof which the environmental impact assessment report has to be \napproved, the proposal is executed without having it approved or if \nany proposal is executed in a manner inconsistent with the approved \nreport.  \n(2) If any person does any act referred to in sub -section (1), the \nconcerned body may give order to stop such act immediately and have the \nenvironmental study report approved pursuant to this Act where such report has \nnot been got approved, and to improve the act if acted inconsistent with such a \nreport, and it shall be the duty of the concerned person or body to do as per the \norder so given. The concerned body may impose a fine that is three -fold of the \nfine imposed pursuant to sub -section (1) if the order so given is not complied with.  \nwww.lawcommission.gov.np \n21 \n \n (3) If any person does any act inconsistent with this Act or the rules, \nguidelines, procedures or norms framed under this Act, other than that set forth in \nsub-section (1), the concerned body may restrict the doing of such act and punish \nthat person with a fin e not exceeding three hundred thousand rupees and give order \nto do the act referred to in this Act or the rules, guidelines, procedures or norms \nframed under this Act. A fine that is three -fold of the fine imposed pursuant to this \nsub-section if the order so given is not complied with.  \n(4) If the act referred to in the order given pursuant to sub -section (2) \nor (3) is not done, such act shall be restricted and the concerned body shall send a \nrequest, accompanied by the recommendation, to take necessary acti on for \nblacklisting such a person or body.  \n(5) If so recommended pursuant to sub -section (4), the Department \nshall, if it finds the content reasonable, blacklist such a person or body for a period \nof one year to five years.  \n(6) Notwithstanding anything con tained in sub -sections (4) and (5), the \nDepartment shall make necessary inquiry into non -compliance with the order \ngiven by it and take action referred to in sub -section (5).  \n(7) If a body is blacklisted pursuant to sub -section (5), such a person  or \nbody m ay not submit any proposal in that body’s name or in any name whatever \nassociated with such a person or body for the period of blacklisting.  \n(8) Prior to imposing the fine referred to in this Section, a reasonable \nopportunity shall be given to the person o r body or project which is to be \nblacklisted.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "36", "title": "Application may be made:  (1) If a person execute s, in contravention of this Act,", "content": "a proposal w ithout having the initial environmental examination, brief \nenvironmental study or environmental impact assessment  report approved or  in a \nmanner inconsistent with the approved report or does or proceeds to do any act \ncontrary to this Act, application may be made to the concerned body or authority.  \n  (2) If any person, body or local community suffers any loss or damage \nas a result of the pollution or disposal of a hazardous waste by another person \ninconsistent with this Act or the rules, guidelines or standards framed under this \nAct, the person, body or local community victimized from such an act may make \nan appli cation to the concerned body for getting compensation for the injury \ncaused to such person , body or community.  \nwww.lawcommission.gov.np \n22 \n \n(3)  If, in examining and inquiring into the  application made pursuant \nto sub -section (1)  or (2) , it is proved that the applicant has sustained l oss or \ndamage, the concerned body shall  ascertain the injury and require a reasonable \ncompensation to be paid by the person, body or proponent who has caused such \nloss or damage to the victim person, body or local community.  \n(4) There shall be formed a com mittee comprising three experts \nnominated by the Government of Nepal to make inquiry into any application made \nas to the injury caused from pollution made by any body of the Government of \nNepal or body owned and controlled by the Government of Nepal, and \ncompensation shall be paid pursuant to sub -section (3) on the basis of \nrecommendation by that committee.  \n(5) There shall be formed a committee comprising three experts \nnominated by the Provincial Government to make inquiry into any application \nmade as to th e injury caused from pollution made by any body of the Provincial \nGovernment or Local Level or body owned and controlled by the Provincial \nGovernment or Local Level, and compensation shall be paid pursuant to sub -\nsection (3) on the basis of recommendation by that committee.  \n(6) The basis for determining compensation pursuant to this Section and \nother provisions shall be as prescribed.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "37", "title": "Appeal:  (1) A party who is not satisfied with the fine imposed pursuant to Section", "content": "35 may make an appeal within thirty -five days to the concerned District Court if \nsuch fine is imposed by the Local Level and to the concerned High Court if it is \nimposed by other b ody or authority of the Government of Nepal or Provincial \nGovernment.  \n  (2) A party who is not satisfied with the decision made as to the \ndetermination of compensation pursuant to Section 36 may make an appeal to the \nconcerned High Court within thirty -five days.", "children": []}]}, {"tier": 1, "nodeType": "chapter", "identifier": "Chapter -7", "title": "Chapter -7", "content": null, "children": [{"tier": 2, "nodeType": "section", "identifier": "38", "title": "Environment protection plan to be formulated:  (1) The Government of Nepal", "content": "may formulate and implement an environment protection plan with a view to \nmaintaining a clean and healthy environment, and conserving and promoting the \nsame.  \nwww.lawcommission.gov.np \n23 \n \n  (2) The Provincial Government and Local Level may, subject to the \nplan referred to in sub -section ( 1), make and implement necessary plans for \nenvironmental protection.  \n  (3) In formulating the plans referred to in sub -sections (1) and (2), \ntraditional and local practices on the protection, conservation, sustainable use of \nthe environment and equitable d istribution of fruits received from the use of \nenvironmental resources shall be included in the plans.  \n  (4) The plan referred to in sub -section (1) shall include such other \nmatters as prescribed.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "39", "title": "Monitoring and inspection to be carried out:  (1) The Ministry or Department", "content": "may carry out monitoring and inspection as to whether or not this Act or the rules, \nguidelines, procedures or standards framed under this Act have been implemented.  \n  (2) The Provincial Government or Local Level may, with a view to \nprotecting and conserving the environment within its area, carry out monitoring \nand inspection as to whether or not this Act or the rules, guidelines, procedures or \nstandards framed under this Act have been implemented.  \n(3) Other provisions relating to monit oring and inspection to be carried \nout pursuant to s ub-section (1)  or (2)  shall  be as prescribe d.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "40", "title": "Annual report to be prepared: (1) The Ministry shall  each year prepare an annual", "content": "report including the following matters:  \n(a) Description obtained from the  monitoring and inspection carried out \npursuant to Section 39,  \n(b) Description relating to national and international activities on \nclimate change,  \n(c) Other necessary description.  \n(2) The Ministry shall submit the annual report referred to in sub -\nsection (1) to the Council within two months of the date of expiry of each fiscal \nyear.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "41", "title": "Power to issue order: (1) The Government of Nepal may, by a notification in the", "content": "Nepal Gazette, issue necessary order as to the matters requiring precautions from \nthe point of view of environmental protection.  \n  (2) The Director General may impose a fine not exceeding one hundred \nthousand rupees on a person or body that violates the order issued pursuant to sub -\nsection (1).  \nwww.lawcommission.gov.np \n24", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "42", "title": "Delegation of power:  The Ministry may, as per necessity, delegate any of the", "content": "powers conferred on it pursuant to this Act to the Department, environmental \ninspector or any office employee or any body .", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "43", "title": "Prevail ing law to govern :  The matters set forth in this Act shall be g overned by", "content": "this Act, and other matters shall be governed by the prevailing law.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "44", "title": "Power to frame rules:  The Government of Nepal may frame necessary rules for", "content": "implementing this Act.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "45", "title": "Power to frame guidelines , procedures and standards : The Government of", "content": "Nepal may, without prejudice to this Act and the rules framed under  this Act , \nframe and enforce  necessary guidelines , procedures and standards.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "46", "title": "Assessment as to implementation of the Act:  (1) The Ministry shall make", "content": "assessment of impacts of the impl ementation of the Act.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "47", "title": "Repeal and saving: (1) The Environment Protection Act, 1997 (2053) is hereby", "content": "repealed.  \n  (2) The acts and actions performed under the Environment Protection \nAct, 1997 (2053) shall be deemed to have been performed under this Act.  \n  (3) If any application or complaint is under consideration by  any body \nor authority pursuant to the Environment Protection Act, 1997  (2053), such \napplication or complaint shall be settled in accordance with that Act .", "children": []}]}]$CODExa79a5959984a$::jsonb) ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title,"originalTitle"=EXCLUDED."originalTitle","documentType"=EXCLUDED."documentType","yearBs"=EXCLUDED."yearBs","yearAd"=EXCLUDED."yearAd","totalPages"=EXCLUDED."totalPages",nodes=EXCLUDED.nodes;
